const m = globalThis.__muster; const w = m.windowId.value;
await m.rpc.call('agent.start', {name: 'orchestrator', window_id: w});
await m.rpc.call('agent.start', {name: 'reviewer', window_id: w});
for (let i = 0; i < 50 && !m.agents.value.find((x) => x.name === 'orchestrator')?.channel_id; i++) await new Promise((r) => setTimeout(r, 100));
const a = m.agents.value.find((x) => x.name === 'orchestrator');
await m.rpc.call('channel.rename', {id: a.channel_id, name: 'planning'});
await m.rpc.call('mock.propose', {agent: 'worker', by: 'orchestrator', name: 'Weekly dependency check', prompt: 'List the dependency updates waiting in the open pull requests and say which are safe to merge.', reason: 'Dependency updates pile up; one look a week is enough.'});
const first = m.windowChannels.value[0]; if (first) m.channelLayout.value = {...m.channelLayout.value, active: first.id};
